<?php
$q = static fn(string $key): string => htmlspecialchars((string)($_GET[$key] ?? ''), ENT_QUOTES, 'UTF-8');
?>
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Pre-Commissioning Report</title>
  <style>
    :root{--red:#d71920;--ink:#172235;--muted:#718096;--line:#dfe4ea;--soft:#f7f9fb;--green:#237a42}*{box-sizing:border-box}body{margin:0;background:#f2f4f7;color:var(--ink);font:14px Inter,Segoe UI,Arial,sans-serif}.wrap{max-width:1050px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:18px;background:#fff;padding:18px 22px;border-radius:12px;border:1px solid var(--line);box-shadow:0 5px 20px #1d2b3a0d}.brand{display:flex;align-items:center;gap:16px}.brand img{width:145px;height:auto}.brand h1{font-size:22px;margin:0}.brand p{margin:4px 0 0;color:var(--muted);font-size:12px}.actions{display:flex;flex-wrap:wrap;gap:8px}.btn{border:1px solid #ccd3dc;background:#fff;border-radius:7px;min-height:40px;padding:0 15px;font-weight:700;color:#485567;cursor:pointer}.btn.primary{background:var(--red);border-color:var(--red);color:#fff}.btn.good{background:var(--green);border-color:var(--green);color:#fff}.card{background:#fff;border:1px solid var(--line);border-radius:12px;margin-top:16px;overflow:hidden}.card-head{padding:14px 18px;background:var(--soft);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.card-head h2{font-size:14px;text-transform:uppercase;letter-spacing:.04em;margin:0}.card-body{padding:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.field.full{grid-column:1/-1}.field label{display:block;font-size:11px;font-weight:800;text-transform:uppercase;color:#667386;margin-bottom:6px}.field input,.field textarea{width:100%;border:1px solid #ced5de;border-radius:7px;padding:10px 11px;background:#fff}.field textarea{min-height:76px;resize:vertical}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{border:1px solid #cfd6df;padding:8px;text-align:left}th{background:#f4f6f8;font-size:11px;text-transform:uppercase}td input{width:100%;border:0;outline:0;padding:3px;background:transparent}.row-btn{border:0;background:none;color:var(--red);font-size:19px;cursor:pointer}.add{margin-top:10px}.hint{font-size:12px;color:var(--muted)}.choice{border:2px dashed #d5dae2;text-align:center;padding:24px;border-radius:10px}.choice input{display:none}.saved{display:none;margin-top:12px;padding:10px 14px;border-radius:7px;background:#eaf7ee;color:var(--green);font-weight:700}.saved.show{display:block}.report-only{display:none}.sig-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:30px;margin-top:35px}.sig{height:65px;border-bottom:1px solid #333;padding-top:44px;font-size:11px;font-style:italic}@media(max-width:700px){.wrap{padding:10px}.top{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}.field.full{grid-column:auto}.actions{width:100%}.btn{flex:1}.sig-grid{grid-template-columns:1fr}}@media print{body{background:#fff;font-size:11px}.wrap{max-width:none;padding:0}.top{box-shadow:none;border:0;padding:0 0 12px}.actions,.choice,.add,.row-btn,.hint,.saved{display:none!important}.card{break-inside:avoid;border-radius:0;margin-top:10px}.card-body{padding:12px}.card-head{padding:9px 12px}input,textarea{border:0!important;padding:0!important}.brand h1{font-size:18px}table{min-width:0}.report-only{display:block}}
    .gas-system{padding-bottom:0}.odu-block{padding-top:4px}.odu-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.odu-title h3{margin:0;font-size:12px;text-transform:uppercase}.odu-table{min-width:520px}.calc-guide{margin:2px 18px 18px;border:1px solid #cfd8e2;border-radius:9px;background:#f8fafc;overflow:hidden}.calc-guide summary{cursor:pointer;padding:13px 15px;font-weight:800;color:#33475b;background:#edf3f7}.calc-body{padding:15px}.formula{padding:10px 12px;margin-bottom:12px;border-left:4px solid #4c6780;background:#fff;line-height:1.65}.formula b{color:#23384c}.reference-table{font-size:11px;min-width:760px}.reference-table th,.reference-table td{text-align:center;padding:6px}.reference-table td:first-child,.reference-table td:nth-child(2){text-align:left}.total-row th{background:#eaf0f5}.total-value{font-weight:800;color:#1f4e78}@media(max-width:700px){.calc-guide{margin:2px 10px 12px}}@media print{.calc-guide{margin:8px 0}.calc-guide summary{list-style:none}}
  </style>
</head>
<body>
<main class="wrap">
  <header class="top">
    <div class="brand"><img src="assets/images/vakharia-airtech-logo.png" alt="Vakharia Airtech"><div><h1>Pre-Commissioning Report</h1><p>Commissioning &middot; Pressure testing &middot; Refrigerant quantity</p></div></div>
    <div class="actions"><button class="btn" type="button" onclick="returnToDaily()">Back</button><button class="btn" type="button" onclick="downloadExcel()">Download Excel</button><button class="btn" type="button" onclick="window.print()">Print / Save PDF</button><button class="btn good" type="button" onclick="saveReport()">Save Report &amp; Return</button></div>
  </header>

  <section class="card">
    <div class="card-head"><h2>Client and system details</h2><span class="hint">Fields marked * are required</span></div>
    <div class="card-body grid">
      <div class="field"><label>Date of commissioning *</label><input id="date" type="date" required></div>
      <div class="field"><label>System / Capacity *</label><input id="system" value="<?= $q('system') ?>" placeholder="e.g. 10 HP" required></div>
      <div class="field"><label>Customer name *</label><input id="customer" value="<?= $q('customer') ?>" required></div>
      <div class="field"><label>Contact person</label><input id="contact" placeholder="Name and mobile number"></div>
      <div class="field full"><label>Address / Project *</label><textarea id="address" required><?= $q('address') ?></textarea></div>
      <div class="field"><label>Email</label><input id="email" type="email"></div>
      <div class="field"><label>Service engineer</label><input id="engineer" value="<?= $q('engineer') ?>"></div>
    </div>
  </section>

  <section class="card">
    <div class="card-head"><h2>1. Commissioning equipment schedule</h2><span class="hint">Enter model, serial and system name</span></div>
    <div class="card-body table-wrap"><table><thead><tr><th>#</th><th>Model No. *</th><th>Serial No. *</th><th>System Name *</th><th>Invoice No.</th><th>Invoice Date</th><th></th></tr></thead><tbody id="units"></tbody></table><button class="btn add" type="button" onclick="addUnit()">+ Add unit</button></div>
    <div class="card-body grid"><div class="field full"><label>Refrigerant amount</label><input id="refrigerant" value="Standard 8 Kg + additional 5.15 Kg = 13.15 Kg" readonly></div><div class="field full"><label>Findings</label><textarea id="findings"></textarea></div></div>
  </section>

  <section class="card">
    <div class="card-head"><h2>2. Pressure testing report</h2><span class="hint">Gas and liquid line readings</span></div>
    <div class="card-body table-wrap"><table><thead><tr><th>Reading</th><th>Type</th><th>Date</th><th>Time</th><th>Temp. &deg;C</th><th>Pressure PSI</th><th>Remarks</th></tr></thead><tbody id="pressure"></tbody></table></div>
  </section>

  <section class="card">
    <div class="card-head"><h2>3. Additional refrigerant gas quantity</h2><span class="hint">Quantity calculates automatically</span></div>
    <div class="card-body grid gas-system"><div class="field full"><label>System / Capacity *</label><input id="gasSystem" value="<?= $q('system') ?>" placeholder="e.g. VRV 10 HP" required></div></div>
    <div class="card-body table-wrap"><table><thead><tr><th>Liquid pipe size (mm)</th><th>Length (Rmt)</th><th>Factor (Kg/m)</th><th>Quantity (Kg)</th></tr></thead><tbody id="pipes"></tbody><tfoot><tr class="total-row"><th>Total pipe length</th><th id="lengthTotal" class="total-value">0.00 Rmt</th><th>Pipe quantity subtotal</th><th id="pipeTotal" class="total-value">0.00 Kg</th></tr><tr><th colspan="3">Table A addition (Kg)</th><th><input id="tableA" type="number" step="0.01" value="1.5" oninput="calcGas()"></th></tr><tr class="total-row"><th colspan="3">Total additional refrigerant</th><th id="gasTotal" class="total-value">1.50 Kg</th></tr></tfoot></table></div>
    <div class="card-body odu-block"><div class="odu-title"><h3>Outdoor Units (ODU)</h3><button class="btn" type="button" onclick="addOdu()">+ Add ODU</button></div><div class="table-wrap"><table class="odu-table"><thead><tr><th>#</th><th>ODU Model</th><th>ODU Serial No.</th><th></th></tr></thead><tbody id="odus"></tbody></table></div></div>
    <details class="calc-guide" open><summary>Calculation instructions and Table A reference</summary><div class="calc-body"><div class="formula"><b>Pipe quantity:</b> Length (Rmt) &times; Factor (kg/m)<br><b>Pipe quantity subtotal:</b> Sum of all pipe quantities<br><b>Diversity / Connection Ratio:</b> (Total IDU capacity &divide; (ODU HP &times; 25)) &times; 100<br><b>Total additional refrigerant:</b> Pipe quantity subtotal + Table A addition</div><div class="table-wrap"><table class="reference-table"><thead><tr><th>Maximum liquid pipe length</th><th>Connection ratio (CR)</th><th>6&ndash;8 HP</th><th>10&ndash;12 HP</th><th>14&ndash;18 HP</th><th>20 HP</th></tr></thead><tbody><tr><td rowspan="4">30 m or less</td><td>50% &le; CR &lt; 105%</td><td>0</td><td>0</td><td>0</td><td>0.5</td></tr><tr><td>105% &le; CR &lt; 130%</td><td>0.5</td><td>0.5</td><td>0.5</td><td>1.0</td></tr><tr><td>130% &le; CR &lt; 160%</td><td>0.5</td><td>0.5</td><td>0.5</td><td>1.3</td></tr><tr><td>160% &le; CR &lt; 200%</td><td>0.5</td><td>0.7</td><td>1.0</td><td>1.5</td></tr><tr><td rowspan="6">More than 30 m</td><td>50% &le; CR &lt; 70%</td><td>0</td><td>0</td><td>0</td><td>0.5</td></tr><tr><td>70% &le; CR &lt; 85%</td><td>0.3</td><td>0.5</td><td>0.5</td><td>1.0</td></tr><tr><td>85% &le; CR &lt; 105%</td><td>0.7</td><td>1.0</td><td>1.0</td><td>1.5</td></tr><tr><td>105% &le; CR &lt; 130%</td><td>1.2</td><td>1.5</td><td>1.5</td><td>2.0</td></tr><tr><td>130% &le; CR &lt; 160%</td><td>1.2</td><td>1.5</td><td>1.5</td><td>2.3</td></tr><tr><td>160% &le; CR &lt; 200%</td><td>1.2</td><td>1.7</td><td>2.0</td><td>2.5</td></tr></tbody></table></div></div></details>
  </section>

  <section class="card"><div class="card-head"><h2>Sign-off</h2></div><div class="card-body sig-grid"><div class="sig">Service Engineer &ndash; Dealer</div><div class="sig">Service Engineer &ndash; Daikin</div><div class="sig">Customer &ndash; Signature &amp; Stamp</div><div class="sig">Consultant &ndash; Signature</div></div></section>

  <section class="card"><div class="card-head"><h2>Or upload completed workbook</h2></div><div class="card-body"><div class="choice"><p><b>Already completed the Excel report?</b></p><p class="hint">Upload .xls or .xlsx. This replaces generated form for daily report.</p><button class="btn primary" type="button" onclick="document.getElementById('upload').click()">Choose Excel File</button><input id="upload" type="file" accept=".xls,.xlsx" onchange="uploadWorkbook(this.files)"></div><div id="saved" class="saved"></div></div></section>
</main>
<script>
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='pmsPreCommissioning:'+new URLSearchParams(location.search).get('project');
const flatIndex=Number(new URLSearchParams(location.search).get('flatIndex'));
const pipeFactors=[[6.4,.022],[9.5,.057],[12.7,.11],[15.9,.17],[19.1,.26],[22.2,.36]];
function addUnit(v={}){const tr=document.createElement('tr');tr.innerHTML=`<td class="num"></td><td><input class="model" value="${esc(v.model)}" required></td><td><input class="serial" value="${esc(v.serial)}" required></td><td><input class="systemName" value="${esc(v.systemName)}" required></td><td><input class="invoice" value="${esc(v.invoice)}"></td><td><input class="invoiceDate" type="date" value="${esc(v.invoiceDate)}"></td><td><button class="row-btn" type="button" onclick="this.closest('tr').remove();renumber()">&times;</button></td>`;$('units').appendChild(tr);renumber()}
function renumber(){[...$('units').rows].forEach((r,i)=>r.querySelector('.num').textContent=i+1)}
function addOdu(v={}){const tr=document.createElement('tr');tr.innerHTML=`<td class="oduNum"></td><td><input class="oduModel" value="${esc(v.model)}" placeholder="e.g. RXMQ10BRY16"></td><td><input class="oduSerial" value="${esc(v.serial)}" placeholder="Serial number"></td><td><button class="row-btn" type="button" onclick="this.closest('tr').remove();renumberOdus()">&times;</button></td>`;$('odus').appendChild(tr);renumberOdus()}
function renumberOdus(){[...$('odus').rows].forEach((r,i)=>r.querySelector('.oduNum').textContent=i+1)}
function pressureRows(){[['Initial','Gas'],['Initial','Liquid'],['Final','Gas'],['Final','Liquid']].forEach(x=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${x[0]}</td><td>${x[1]}</td><td><input class="pdate" type="date"></td><td><input class="ptime" type="time"></td><td><input class="ptemp" type="number" value="30"></td><td><input class="ppsi" type="number" value="580"></td><td><input class="premarks" value="HOLD"></td>`;$('pressure').appendChild(tr)})}
function pipeRows(){pipeFactors.forEach(x=>{const tr=document.createElement('tr');tr.innerHTML=`<td class="size">${x[0]}</td><td><input class="length" type="number" min="0" step="0.01" oninput="calcGas()"></td><td class="factor">${x[1]}</td><td class="qty">0.00</td>`;$('pipes').appendChild(tr)})}
function calcGas(){let quantity=0,length=0;[...$('pipes').rows].forEach(r=>{const len=+r.querySelector('.length').value||0;const q=len*(+r.querySelector('.factor').textContent||0);r.querySelector('.qty').textContent=q.toFixed(2);length+=len;quantity+=q});$('lengthTotal').textContent=length.toFixed(2)+' Rmt';$('pipeTotal').textContent=quantity.toFixed(2)+' Kg';$('gasTotal').textContent=(quantity+(+$('tableA').value||0)).toFixed(2)+' Kg'}
function values(sel){return [...document.querySelectorAll(sel)].map(x=>x.value)}
function collect(){const pipes=[...$('pipes').rows].map(r=>({size:r.querySelector('.size').textContent,length:+r.querySelector('.length').value||0,factor:+r.querySelector('.factor').textContent,quantity:+r.querySelector('.qty').textContent||0}));const odus=[...$('odus').rows].map(r=>({model:r.querySelector('.oduModel').value.trim(),serial:r.querySelector('.oduSerial').value.trim()}));return{date:$('date').value,system:$('system').value.trim(),gasSystem:$('gasSystem').value.trim(),customer:$('customer').value.trim(),contact:$('contact').value.trim(),address:$('address').value.trim(),email:$('email').value.trim(),engineer:$('engineer').value.trim(),refrigerant:$('refrigerant').value.trim(),findings:$('findings').value.trim(),odus,oduModel:odus[0]?.model||'',oduSerial:odus[0]?.serial||'',tableA:+$('tableA').value||0,units:[...$('units').rows].map(r=>({model:r.querySelector('.model').value.trim(),serial:r.querySelector('.serial').value.trim(),systemName:r.querySelector('.systemName').value.trim(),invoice:r.querySelector('.invoice').value.trim(),invoiceDate:r.querySelector('.invoiceDate').value})),pressure:[...$('pressure').rows].map(r=>({reading:r.cells[0].textContent,type:r.cells[1].textContent,date:r.querySelector('.pdate').value,time:r.querySelector('.ptime').value,temp:r.querySelector('.ptemp').value,psi:r.querySelector('.ppsi').value,remarks:r.querySelector('.premarks').value.trim()})),pipes,totalLength:pipes.reduce((s,p)=>s+p.length,0),pipeSubtotal:pipes.reduce((s,p)=>s+p.quantity,0),totalGas:parseFloat($('gasTotal').textContent)||0,createdAt:new Date().toISOString()}}
function valid(r){if(!r.date||!r.system||!r.gasSystem||!r.customer||!r.address){alert('Complete date, system, refrigerant system, customer and address.');return false}if(!r.units.length||r.units.some(u=>!u.model||!u.serial||!u.systemName)){alert('Enter model, serial and system name for every unit.');return false}if(!r.odus.length||r.odus.some(o=>!o.model||!o.serial)){alert('Enter model and serial number for every ODU row.');return false}return true}
function updateDailyDraft(report,file){let draft={};try{draft=JSON.parse(localStorage.getItem('vakhariaSiteVisitDraft')||'{}')||{}}catch(e){}const apply=target=>{target.preCommissioningReport=report||null;target.preCommissioningFile=file||null};if(Number.isInteger(flatIndex)&&flatIndex>=0&&Array.isArray(draft.flats)&&draft.flats[flatIndex])apply(draft.flats[flatIndex]);if(!Number.isInteger(flatIndex)||flatIndex<0||draft.activeFlat===flatIndex)apply(draft);localStorage.setItem('vakhariaSiteVisitDraft',JSON.stringify(draft))}
function returnToDaily(){window.location.href='./'}
function saveReport(){const r=collect();if(!valid(r))return;localStorage.setItem(storageKey,JSON.stringify(r));updateDailyDraft(r,null);$('saved').textContent='Report saved and attached. Returning to daily report...';$('saved').classList.add('show');setTimeout(returnToDaily,450)}
function uploadWorkbook(files){const f=files&&files[0];if(!f)return;if(!/\.(xls|xlsx)$/i.test(f.name)){alert('Select an .xls or .xlsx file.');return}if(f.size>10*1024*1024){alert('Excel file must be 10 MB or smaller.');return}const reader=new FileReader();reader.onload=()=>{const file={name:f.name,mimeType:f.type||'application/vnd.ms-excel',base64:String(reader.result).split(',')[1]||''};updateDailyDraft(null,file);$('saved').textContent=f.name+' attached. Returning to daily report...';$('saved').classList.add('show');setTimeout(returnToDaily,450)};reader.readAsDataURL(f)}
function sheetHtml(r){const rows=r.units.map((u,i)=>`<tr><td>${i+1}</td><td>${esc(u.model)}</td><td>${esc(u.serial)}</td><td>${esc(u.systemName)}</td><td>${esc(u.invoice)}</td><td>${esc(u.invoiceDate)}</td></tr>`).join('');const press=r.pressure.map(x=>`<tr><td>${x.reading}</td><td>${x.type}</td><td>${x.date}</td><td>${x.time}</td><td>${x.temp}</td><td>${x.psi}</td><td>${esc(x.remarks)}</td></tr>`).join('');const pipes=r.pipes.map(x=>`<tr><td>${x.size}</td><td>${x.length}</td><td>${x.factor}</td><td>${x.quantity.toFixed(2)}</td></tr>`).join('');const odus=r.odus.map((o,i)=>`<tr><td>${i+1}</td><td>${esc(o.model)}</td><td>${esc(o.serial)}</td></tr>`).join('');return `<html><head><meta charset="utf-8"></head><body><table border="1"><tr><th colspan="7">Commissioning Report Side Discharge</th></tr><tr><td>Date</td><td colspan="6">${r.date}</td></tr><tr><td>Customer</td><td colspan="6">${esc(r.customer)}</td></tr><tr><td>Address</td><td colspan="6">${esc(r.address)}</td></tr><tr><td>Contact</td><td colspan="6">${esc(r.contact)}</td></tr><tr><td>Email</td><td colspan="6">${esc(r.email)}</td></tr><tr><td>System</td><td colspan="6">${esc(r.system)}</td></tr><tr><th>#</th><th>Model No.</th><th>Sr. No.</th><th>System Name</th><th>Invoice No.</th><th>Date</th></tr>${rows}<tr><td>Refrigerant amount</td><td colspan="6">${esc(r.refrigerant)}</td></tr><tr><td>Findings</td><td colspan="6">${esc(r.findings)}</td></tr></table><br><table border="1"><tr><th colspan="7">Pressure Testing Report</th></tr><tr><th>Reading</th><th>Type</th><th>Date</th><th>Time</th><th>Temp C</th><th>Pressure PSI</th><th>Remarks</th></tr>${press}</table><br><table border="1"><tr><th colspan="3">Outdoor Units</th></tr><tr><th>#</th><th>ODU Model</th><th>ODU Serial No.</th></tr>${odus}</table><br><table border="1"><tr><th colspan="4">Additional Refrigerant Gas Quantity</th></tr><tr><td>System</td><td colspan="3">${esc(r.gasSystem)}</td></tr><tr><th>Size</th><th>Length Rmt</th><th>Factor</th><th>Quantity Kg</th></tr>${pipes}<tr><th>Total pipe length</th><th>${r.totalLength.toFixed(2)} Rmt</th><th>Pipe quantity subtotal</th><th>${r.pipeSubtotal.toFixed(2)} Kg</th></tr><tr><th colspan="3">Table A addition</th><th>${r.tableA.toFixed(2)} Kg</th></tr><tr><th colspan="3">Total additional refrigerant</th><th>${r.totalGas.toFixed(2)} Kg</th></tr></table><p><b>Calculation:</b> Pipe quantity = Length x Factor. Total additional refrigerant = Pipe quantity subtotal + Table A addition.</p></body></html>`}
function downloadExcel(){const r=collect();if(!valid(r))return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([sheetHtml(r)],{type:'application/vnd.ms-excel'}));a.download='Pre-Commissioning_Report_'+(r.customer||'Project').replace(/[^a-z0-9]+/gi,'_')+'.xls';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function restore(r){if(!r)return;['date','system','gasSystem','customer','contact','address','email','engineer','findings','tableA'].forEach(k=>{if(r[k]!==undefined&&$(k))$(k).value=r[k]});$('refrigerant').value='Standard 8 Kg + additional 5.15 Kg = 13.15 Kg';$('units').innerHTML='';(r.units||[]).forEach(addUnit);$('odus').innerHTML='';const oldOdus=(r.odus&&r.odus.length)?r.odus:((r.oduModel||r.oduSerial)?[{model:r.oduModel||'',serial:r.oduSerial||''}]:[]);oldOdus.forEach(addOdu);if(!$('odus').rows.length)addOdu();if(!r.gasSystem)$('gasSystem').value=r.system||$('system').value;[...$('pressure').rows].forEach((row,i)=>{const p=(r.pressure||[])[i];if(!p)return;row.querySelector('.pdate').value=p.date||'';row.querySelector('.ptime').value=p.time||'';row.querySelector('.ptemp').value=p.temp||'';row.querySelector('.ppsi').value=p.psi||'';row.querySelector('.premarks').value=p.remarks||''});[...$('pipes').rows].forEach((row,i)=>{const p=(r.pipes||[])[i];if(p)row.querySelector('.length').value=p.length||''});calcGas()}
$('date').value=new Date().toISOString().slice(0,10);pressureRows();pipeRows();addUnit();addOdu();try{restore(JSON.parse(localStorage.getItem(storageKey)||'null'))}catch(e){}
</script>
</body></html>
